INSERT INTO MEDICAL_RECORD (record_id, appointment_id, patient_id, specialist_id, diagnosis, clinical_notes, treatment_plan, record_date, deleted_at) VALUES
('94fbb05b-725e-4e3d-ae20-f4e85d4bc0a1', '99244963-8168-443c-9a8e-4b4a4251c3f6', 'd7cf0dcd-faae-4e39-8879-c562429097d8', 'ec95c791-7e6d-431a-8c49-8c8bbb854b03', 'Thoái hóa khớp gối nguyên phát kèm đau cơ quanh khớp (ICD-10: M17.0)', 'Đau khớp gối 2 bên tăng khi đi lại hoặc lên xuống cầu thang, có tiếng lạo xạo khi vận động, không sưng nóng đỏ.', 'Uống thuốc giảm đau kháng viêm sau ăn no, hạn chế mang vác nặng, tập vận động co duỗi khớp gối không tải.', '2026-09-03 09:30:00', NULL),
('703bc06b-b9ff-4d27-b31d-94e21cb8bb02', '0ef4fcba-c4ff-406c-a2ec-be73099d9216', '5f484307-7e25-4a7d-afcd-f449606e9315', '86d94088-56b1-4497-9744-28efe54534a6', 'Viêm phế quản cấp thể co thắt (ICD-10: J20.9)', 'Ho khan từng cơn nhiều về đêm, có đờm trắng loãng, đau rát họng, nghe phổi có ít rale rít rải rác.', 'Kháng sinh đủ liều 7 ngày, uống nhiều nước ấm, súc họng nước muối, xịt giãn phế quản khi khó thở nhiều.', '2026-09-03 09:00:00', NULL),
('2d6884ec-e70f-4151-b1a7-b49db39c02a6', '855aa92c-ad46-4785-aa8b-513443e6a962', '5cec4053-0f34-4a2f-8c9a-ec0c8d6802f9', 'a2ef2836-d5f7-48a9-a9e6-de8f5e4cc8df', 'Tăng huyết áp vô căn độ 2 (ICD-10: I10)', 'Huyết áp phòng khám 150/95 mmHg, nhịp tim 82 l/p. Tiếng tim T1, T2 đều rõ. Chưa ghi nhận phù ngoại biên.', 'Kiểm soát huyết áp bằng thuốc hàng ngày, hạn chế ăn mặn (<5g muối/ngày), tập thể dục nhẹ nhàng 30p/ngày.', '2026-09-12 14:00:00', NULL),
('108004bd-fff5-4aef-9bc2-28ec4334cbef', '37469e5b-79aa-4ec1-bd1f-0ef1fde039c8', '80fad4bf-5eb9-4002-890f-ddfbf9d403be', 'fd11c8af-b05f-47bf-b656-1361ecb9758c', 'Viêm mũi xoang dị ứng đợt cấp (ICD-10: J30.4)', 'Ngạt mũi, hắt hơi thành tràng liên tục khi gặp lạnh, chảy dịch mũi trong, ngứa mũi và mắt.', 'Xịt rửa mũi bằng nước muối sinh lý hàng ngày, xịt thuốc co mạch mũi khi ngạt nặng, uống kháng histamine.', '2026-09-04 14:30:00', NULL),
